import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Build two shards, each holding a different slice of the document corpus,
        // exactly like document-id-range partitioning in the real design.
        SearchShard shardA = new SearchShard("A");
        shardA.indexDocument(1, "the quick brown fox jumps over the lazy dog");
        shardA.indexDocument(2, "a quick fox runs through the forest");
        shardA.indexDocument(3, "search engines index web pages for fast retrieval");

        SearchShard shardB = new SearchShard("B");
        shardB.indexDocument(4, "web crawlers fetch pages across the internet");
        shardB.indexDocument(5, "fast search requires an inverted index of terms");

        ScatterGatherCoordinator coordinator = new ScatterGatherCoordinator(Arrays.asList(shardA, shardB));

        System.out.println("Query: \"quick fox\"");
        List<ScoredDoc> results1 = coordinator.search("quick fox", 5, Collections.emptySet());
        for (ScoredDoc doc : results1) {
            System.out.println("  docId=" + doc.docId + " score=" + doc.score);
        }

        System.out.println("Query: \"search index\"");
        List<ScoredDoc> results2 = coordinator.search("search index", 5, Collections.emptySet());
        for (ScoredDoc doc : results2) {
            System.out.println("  docId=" + doc.docId + " score=" + doc.score);
        }

        System.out.println("Query: \"search index\" with shard B excluded (simulated timeout)");
        List<ScoredDoc> results3 = coordinator.search("search index", 5, Collections.singleton("B"));
        for (ScoredDoc doc : results3) {
            System.out.println("  docId=" + doc.docId + " score=" + doc.score);
        }
        System.out.println("Query still completed despite the excluded shard: " + true);
    }
}

// One document's score after matching against a query.
class ScoredDoc {
    int docId;      // which document this score belongs to
    double score;   // the computed relevance score, higher is more relevant

    ScoredDoc(int docId, double score) {
        this.docId = docId;
        this.score = score;
    }
}

// One index shard: holds an inverted index for its own slice of the corpus
// and can locally score and rank a query against only its own documents.
class SearchShard {
    private final String shardId;                                   // this shard's identifier, e.g. "A"
    private final Map<String, Map<Integer, Integer>> postings = new HashMap<>(); // term -> docId -> term frequency

    SearchShard(String shardId) {
        this.shardId = shardId; // remember which shard this is, for the coordinator's exclusion logic
    }

    String getShardId() {
        return shardId;
    }

    // Adds a document's text to this shard's inverted index.
    void indexDocument(int docId, String text) {
        String[] terms = text.toLowerCase().split("\\s+"); // split into lowercase terms on whitespace
        for (String term : terms) {
            postings.computeIfAbsent(term, t -> new HashMap<>()) // get or create this term's posting list
                    .merge(docId, 1, Integer::sum);              // increment this document's term frequency by 1
        }
    }

    // Scores every document in this shard against the query's terms, returning
    // the top k highest-scoring documents that matched at least one query term.
    List<ScoredDoc> localTopK(String query, int k) {
        String[] queryTerms = query.toLowerCase().split("\\s+");     // the query's own terms
        Map<Integer, Double> scoresByDoc = new HashMap<>();          // docId -> accumulated score

        for (String term : queryTerms) {
            Map<Integer, Integer> termPostings = postings.get(term); // this term's posting list, if any
            if (termPostings == null) continue;                       // no document in this shard has this term
            for (Map.Entry<Integer, Integer> entry : termPostings.entrySet()) {
                int docId = entry.getKey();
                int termFrequency = entry.getValue();
                // Simple term-frequency-based score: each matching term contributes
                // its raw frequency in this document, summed across all query terms.
                scoresByDoc.merge(docId, (double) termFrequency, Double::sum);
            }
        }

        List<ScoredDoc> scored = new ArrayList<>();
        for (Map.Entry<Integer, Double> entry : scoresByDoc.entrySet()) {
            scored.add(new ScoredDoc(entry.getKey(), entry.getValue())); // only documents that matched at least one term
        }
        scored.sort((a, b) -> Double.compare(b.score, a.score)); // highest score first
        return scored.size() > k ? scored.subList(0, k) : scored; // truncate to the requested top k
    }
}

// Fans a query out to every shard in parallel (simulated here as a simple loop),
// skipping any shard listed as unavailable, and merges the responses into one
// final ranked list, exactly matching the real design's scatter-gather pattern.
class ScatterGatherCoordinator {
    private final List<SearchShard> shards; // every shard this coordinator knows about

    ScatterGatherCoordinator(List<SearchShard> shards) {
        this.shards = shards;
    }

    // unavailableShardIds simulates shards that timed out or failed for this query;
    // they are simply excluded, the query still completes with the rest.
    List<ScoredDoc> search(String query, int k, Set<String> unavailableShardIds) {
        List<ScoredDoc> merged = new ArrayList<>(); // collects every responding shard's local top results

        for (SearchShard shard : shards) {
            if (unavailableShardIds.contains(shard.getShardId())) {
                continue; // this shard is excluded, exactly like a timed-out shard in the real design
            }
            merged.addAll(shard.localTopK(query, k)); // gather this shard's contribution
        }

        merged.sort((a, b) -> Double.compare(b.score, a.score)); // re-rank the combined candidates by score
        return merged.size() > k ? merged.subList(0, k) : merged;  // truncate to the requested global top k
    }
}

