#include <vector>

// One document's score after matching against a query.
struct ScoredDoc {
    int docId;       // which document this score belongs to
    double score;    // the computed relevance score, higher is more relevant
};

// One index shard: holds an inverted index for its own slice of the corpus
// and can locally score and rank a query against only its own documents.
class SearchShard {
public:
    explicit SearchShard(std::string shardId) : shardId_(std::move(shardId)) {}

    const std::string& getShardId() const { return shardId_; }   // remember which shard this is, for the coordinator's exclusion logic

    // Adds a document's text to this shard's inverted index.
    void indexDocument(int docId, const std::string& text) {
        for (auto& term : tokenize(text)) {                             // split into lowercase terms on whitespace
            postings_[term][docId]++;                                      // increment this document's term frequency by 1
        }
    }

    // Scores every document in this shard against the query's terms, returning
    // the top k highest-scoring documents that matched at least one query term.
    std::vector<ScoredDoc> localTopK(const std::string& query, int k) {
        auto queryTerms = tokenize(query);                              // the query's own terms
        std::map<int, double> scoresByDoc;                                 // docId -> accumulated score

        for (auto& term : queryTerms) {
            auto it = postings_.find(term);                                 // this term's posting list, if any
            if (it == postings_.end()) continue;                             // no document in this shard has this term
            for (auto& [docId, termFrequency] : it->second) {
                // Simple term-frequency-based score: each matching term contributes
                // its raw frequency in this document, summed across all query terms.
                scoresByDoc[docId] += termFrequency;
            }
        }

        std::vector<ScoredDoc> scored;                                    // only documents that matched at least one term
        for (auto& [docId, score] : scoresByDoc) scored.push_back({ docId, score });
        std::stable_sort(scored.begin(), scored.end(), [](auto& a, auto& b) { return a.score > b.score; });   // highest score first
        if (static_cast<int>(scored.size()) > k) scored.resize(k);          // truncate to the requested top k
        return scored;
    }

private:
    std::vector<std::string> tokenize(const std::string& text) {
        std::vector<std::string> words;
        std::string lower = text;
        for (auto& c : lower) c = static_cast<char>(::tolower(static_cast<unsigned char>(c)));
        std::istringstream iss(lower);
        std::string w;
        while (iss >> w) words.push_back(w);
        return words;
    }

    std::string shardId_;
    std::map<std::string, std::map<int, int>> postings_;   // term -> docId -> term frequency
};

// Fans a query out to every shard in parallel (simulated here as a simple loop),
// skipping any shard listed as unavailable, and merges the responses into one
// final ranked list, exactly matching the real design's scatter-gather pattern.
class ScatterGatherCoordinator {
public:
    explicit ScatterGatherCoordinator(std::vector<SearchShard*> shards) : shards_(std::move(shards)) {}

    // unavailableShardIds simulates shards that timed out or failed for this query;
    // they are simply excluded, the query still completes with the rest.
    std::vector<ScoredDoc> search(const std::string& query, int k, const std::set<std::string>& unavailableShardIds) {
        std::vector<ScoredDoc> merged;   // collects every responding shard's local top results

        for (auto* shard : shards_) {
            if (unavailableShardIds.count(shard->getShardId())) {
                continue;   // this shard is excluded, exactly like a timed-out shard in the real design
            }
            auto local = shard->localTopK(query, k);
            merged.insert(merged.end(), local.begin(), local.end());   // gather this shard's contribution
        }

        std::stable_sort(merged.begin(), merged.end(), [](auto& a, auto& b) { return a.score > b.score; });   // re-rank the combined candidates by score
        if (static_cast<int>(merged.size()) > k) merged.resize(k);        // truncate to the requested global top k
        return merged;
    }

private:
    std::vector<SearchShard*> shards_;   // every shard this coordinator knows about
};

std::string formatScore(double score) {
    // mirror Java's double toString for whole numbers (always shows ".0")
    std::ostringstream oss;
    if (score == static_cast<long long>(score)) oss << static_cast<long long>(score) << ".0";
    else oss << score;
    return oss.str();
}

int main() {
    std::cout << std::boolalpha;

    // Build two shards, each holding a different slice of the document corpus,
    // exactly like document-id-range partitioning in the real design.
    SearchShard shardA("A");
    shardA.indexDocument(1, "the quick brown fox jumps over the lazy dog");
    shardA.indexDocument(2, "a quick fox runs through the forest");
    shardA.indexDocument(3, "search engines index web pages for fast retrieval");

    SearchShard shardB("B");
    shardB.indexDocument(4, "web crawlers fetch pages across the internet");
    shardB.indexDocument(5, "fast search requires an inverted index of terms");

    ScatterGatherCoordinator coordinator({ &shardA, &shardB });

    std::cout << "Query: \"quick fox\"\n";
    auto results1 = coordinator.search("quick fox", 5, {});
    for (auto& doc : results1) std::cout << "  docId=" << doc.docId << " score=" << formatScore(doc.score) << "\n";

    std::cout << "Query: \"search index\"\n";
    auto results2 = coordinator.search("search index", 5, {});
    for (auto& doc : results2) std::cout << "  docId=" << doc.docId << " score=" << formatScore(doc.score) << "\n";

    std::cout << "Query: \"search index\" with shard B excluded (simulated timeout)\n";
    auto results3 = coordinator.search("search index", 5, { "B" });
    for (auto& doc : results3) std::cout << "  docId=" << doc.docId << " score=" << formatScore(doc.score) << "\n";
    std::cout << "Query still completed despite the excluded shard: " << true << "\n";
    return 0;
}

